# =============================================================================
# IrineCore — Default Build & CLI Configuration Template (conf/dist/config.sh)
# =============================================================================
# DO NOT EDIT THIS FILE DIRECTLY.
# Copy to `conf/config.sh` (gitignored) and override only the variables you need.
# Both `./irine.sh` and `./apps/compiler/compile.sh` load:
#   1. conf/dist/config.sh  (tracked defaults)
#   2. conf/config.sh       (optional local user overrides)
# =============================================================================

# CMake build type: Release | RelWithDebInfo | Debug
IRINE_BUILD_TYPE="${IRINE_BUILD_TYPE:-Release}"

# Build and staged distribution directories (relative to repo root or absolute)
IRINE_BUILD_DIR="${IRINE_BUILD_DIR:-build}"
IRINE_DIST_DIR="${IRINE_DIST_DIR:-env/dist}"

# Module build mode: static | disabled
IRINE_MODULES="${IRINE_MODULES:-static}"

# Semicolon-separated list of module folder names to skip (e.g. "Player-Bots;examples")
DISABLED_IRINE_MODULES="${DISABLED_IRINE_MODULES:-}"

# Build auxiliary packaging/patching tools: ON | OFF
IRINE_BUILD_TOOLS="${IRINE_BUILD_TOOLS:-ON}"

# Enable ccache automatically when installed: ON | OFF
IRINE_USE_CCACHE="${IRINE_USE_CCACHE:-ON}"

# Parallel compile job count (empty = auto-detect CPU cores)
IRINE_BUILD_JOBS="${IRINE_BUILD_JOBS:-}"

# Optional extra CMake configure arguments (array)
IRINE_CMAKE_EXTRA_ARGS=()

# Number of rotated log backups to keep via `./irine.sh server rotate-logs`
IRINE_LOG_ROTATE_KEEP="${IRINE_LOG_ROTATE_KEEP:-5}"
